namespace Cratis.Chronicle.Storage.Events.Constraints.V2;

/// <summary>
/// Represents the store-level marker epoch copied into each constraint's authority row.
/// </summary>
/// <param name="Value">The nonempty epoch supplied by future cutover, not generated by storage.</param>
public sealed record UniqueConstraintEpoch(Guid Value) : ConceptAs<Guid>(Value != Guid.Empty ? Value : throw new InvalidUniqueConstraintV2Input(nameof(UniqueConstraintEpoch)));
